<?php require dirname(__DIR__,2).'/layouts/admin_start.php';$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$week=[1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',0=>'Dom'];?>
<form method="post" class="card sampling-admin"><input type="hidden" name="_csrf" value="<?=$e($csrf)?>"><header><p>Uma alteração cria nova vigência; consultas históricas continuam usando a regra válida no período.</p><label>Vigência a partir de<input type="date" name="effective_from" value="<?=date('Y-m-d')?>" required></label></header><div class="table-wrap"><table><thead><tr><th>Hemocomponente</th><?php foreach($week as$label):?><th><?=$label?></th><?php endforeach?><th>Percentual</th><th>Mínimo</th><th>Pequena produção</th><th>Limite</th><th>Fonte de produção</th></tr></thead><tbody><?php foreach($components as$c):$id=(int)$c['id'];?><tr><td><b><?=$e($c['code'])?></b><small><?=$e($c['name'])?></small></td><?php foreach($week as$day=>$label):?><td><input type="checkbox" name="days[<?=$id?>][<?=$day?>]" value="1" <?=in_array($day,$days[$id]??[],true)?'checked':''?>></td><?php endforeach?><td><input type="number" step="0.01" min="0" name="rules[<?=$id?>][percentage]" value="<?=$e($c['percentage'])?>"></td><td><input type="number" min="0" name="rules[<?=$id?>][minimum_units]" value="<?=$e($c['minimum_units'])?>"></td><td><select name="rules[<?=$id?>][small_production_mode]"><option value="standard">Padrão</option><option value="actual_up_to_limit" <?=$c['small_production_mode']==='actual_up_to_limit'?'selected':''?>>Produção real</option></select></td><td><input type="number" min="1" name="rules[<?=$id?>][small_production_limit]" value="<?=$e($c['small_production_limit'])?>"></td><td><select name="rules[<?=$id?>][source_id]"><option value="">Própria</option><?php foreach($sources as$s):if((int)$s['id']===$id)continue;?><option value="<?=$s['id']?>" <?=(int)$c['source_blood_component_id']===(int)$s['id']?'selected':''?>><?=$e($s['code'])?> — <?=$e($s['name'])?></option><?php endforeach?></select></td></tr><?php endforeach?></tbody></table></div><footer><button class="button button-primary">Salvar nova vigência</button></footer></form>
